WITH valid_inventory AS (SELECT *, ROUND(quantity * 1.07, 2) AS quantity_adjusted FROM inventory WHERE product_id IN (2, 7, 8)), inventory_stats AS (SELECT DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, store_id, AVG(quantity) AS avg_quantity FROM valid_inventory GROUP BY DATE_FORMAT(last_restock, 'yyyy-MM'), store_id) SELECT * FROM inventory_stats WHERE avg_quantity > 80 ORDER BY store_id DESC, last_restock_month LIMIT 1
